<template>
  <el-drawer :model-value="open" @update:model-value="emit('update:open',$event)" :title="node?.name || `${country?.name || ''}供应政策`" size="min(640px,95vw)" append-to-body>
    <template v-if="node"><div class="node-summary"><el-tag>{{ node.node_kind || node.type }}</el-tag><el-tag effect="plain">{{ node.aggregation_level==='EXACT_PUBLIC_ENTITY'?'具体公开主体':node.aggregation_level==='PUBLIC_TRANSPORT_NODE'?'公开交通节点':'区域 / 网络聚合' }}</el-tag><p>{{ node.description }}</p></div><el-descriptions :column="1" border><el-descriptions-item label="国家 / 区域">{{ node.country_name || node.country_id || '待补全' }}</el-descriptions-item><el-descriptions-item label="真实主体依据">{{ node.real_entity || '未绑定具体企业或设施，按聚合节点呈现' }}</el-descriptions-item><el-descriptions-item label="材料与产品">{{ node.material || '待补全' }}</el-descriptions-item><el-descriptions-item label="运输方式">{{ node.transport_mode || '待补全' }}</el-descriptions-item><el-descriptions-item label="坐标口径">{{ node.coordinate_basis || '用户坐标' }}</el-descriptions-item><el-descriptions-item label="资料时间">{{ node.as_of || '待补全' }}</el-descriptions-item></el-descriptions>
      <h3 v-if="displayMetrics.length">业务指标</h3><div v-for="metric in displayMetrics" :key="metric.label" class="metric"><strong>{{ metric.label }}</strong><span>{{ metric.value == null ? '待补全' : `${metric.value} ${metric.unit}` }}</span><small>{{ metric.basis }}{{ metric.as_of ? ` · ${metric.as_of}` : '' }}</small></div>
      <template v-if="publicEntities.length"><h3>关联主体公开数据</h3><p v-if="!isCanada" class="source">以下属于具体矿山或设施，不等同于整个供应国的产能，也不证明其参与某批次对华交付。</p><article v-for="entity in publicEntities" :key="entity.subject_id" class="connection"><strong>{{ entity.name }}</strong><div v-for="fact in entity.facts" :key="fact.fact_id" class="metric"><strong>{{ factLabel(fact.indicator) }}</strong><span>{{ fact.value }} {{ fact.unit }}</span><small>{{ fact.data_year }} · {{ fact.document_id }} · {{ fact.value_semantics }}<br>证据：{{ fact.evidence_ids?.join('、') }}</small></div><p v-if="!entity.facts.length">产能、产量、库存等量化数据待补全。</p></article></template><h3>供需与通道联系</h3><div v-for="edge in connections" :key="edge.id" class="connection"><strong>{{ nameOf(edge.source_id) }} → {{ nameOf(edge.target_id) }}</strong><p>{{ edge.label }}</p><small>{{ edge.evidence_level==='DIRECT'?'直接来源支持':edge.evidence_level==='INDIRECT'?'间接证据支持':'关系依据待补全' }}</small></div><p v-if="!connections.length">暂无已绑定联系。</p><h3>数据来源</h3><p class="source" v-for="source in node.source_refs || []" :key="source">{{ source }}</p><small>{{ node.source }}</small>
    </template>
    <h3>{{ country?.name || '供应国' }}相关政策</h3><template v-if="country"><article v-for="item in country.items" :key="item.title" class="policy"><strong>{{ item.title }}</strong><p>{{ item.summary }}</p><dl><dt>范围</dt><dd>{{ item.scope }}</dd><dt>建模影响</dt><dd>{{ item.effect }}</dd><dt>时间依据</dt><dd>{{ item.period }}</dd></dl><a :href="item.url" target="_blank" rel="noopener noreferrer">{{ item.authority }} · 查看原始来源 ↗</a></article></template><p v-else>该节点未绑定供应国政策；请选择海外供应节点或供应国家区域。</p><section v-if="isCanada" class="canada-events"><h3>加拿大供应链历史事件 · {{ canadaEvents.length }} 条</h3><p class="source">按时间倒序展示。事件当时的运行状态、预测与后续恢复分别记录，不代表当前仍在持续。</p><article v-for="event in canadaEvents" :key="event.date+event.title" class="event-card"><div class="event-date">{{ event.date }}<el-tag size="small" effect="plain">{{ event.category }}</el-tag></div><strong>{{ event.title }}</strong><p>{{ event.summary }}</p><dl><dt>关联主体</dt><dd>{{ event.actors }}</dd><dt>供应链影响</dt><dd>{{ event.impact }}</dd><dt>建模映射</dt><dd>{{ event.mapping }}<small>（映射建议，不是已计算结果）</small></dd><dt>记录性质</dt><dd>{{ event.status }}</dd></dl><a :href="event.url" target="_blank" rel="noopener noreferrer">Cameco 官方披露 · 查看原始来源 ↗</a></article></section><p class="foot">政策信息作为环境约束的来源记录；批次许可、当前税率和审批状态需要绑定相应业务文件。</p>
  </el-drawer>
</template>
<script setup>
import { computed } from 'vue'
import { canadaSupplyEvents } from '@/utils/canadaUraniumProfile'
import { policyCountry } from '@/utils/uraniumCountryPolicies'
const props=defineProps({open:Boolean,node:{type:Object,default:null},countryId:{type:String,default:''},world:{type:Object,default:null}}),emit=defineEmits(['update:open'])
const country=computed(()=>policyCountry(props.countryId||props.node?.supplier_country||props.node?.country_id))
const isCanada=computed(()=>country.value?.name==='加拿大')
const displayMetrics=computed(()=>(props.node?.metrics||[]).filter(metric=>!isCanada.value||metric.value!=null))
const publicEntities=computed(()=>(props.node?.related_entities||[]).filter(entity=>!isCanada.value||entity.facts?.length&&!['facility_jeb_tmf','facility_jeb_wtp','facility_key_lake_mill'].includes(entity.subject_id)))
const canadaEvents=canadaSupplyEvents
const connections=computed(()=>props.node?(props.world?.edges||[]).filter(x=>x.source_id===props.node.entity_id||x.target_id===props.node.entity_id):[])
const factLabel=id=>({uranium_production:'实际年度铀产量',uranium_production_target:'年度产量目标',cameco_share:'Cameco权益份额',kazatomprom_share:'Kazatomprom权益份额',cameco_ownership_share:'Cameco所有权份额',mine_status:'矿山状态',operator:'运营主体',sulphuric_acid_supply_constraint:'硫酸供应约束',production_guidance_reduction_2025:'2025年产量指引调整',planned_maintenance_shutdown:'计划检修',mill_ore_feed:'选冶厂给矿量',wtp_shutdown:'水处理设施停运记录'}[id]||id)
const nameOf=id=>props.world?.nodes.find(x=>x.entity_id===id)?.name||id
</script>
<style scoped>
.node-summary p,.policy p,.connection p,.source{font-size:12px;line-height:1.9;color:#64748b}.node-summary .el-tag{margin:0 8px 8px 0}h3{font-size:14px;color:#334155;margin:24px 0 12px}.metric{display:grid;grid-template-columns:1fr auto;gap:6px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:7px;padding:12px;margin:8px 0;font-size:12px}.metric small{grid-column:1/-1;color:#94a3b8}.connection,.policy{padding:14px;border:1px solid #e2e8f0;border-radius:8px;margin:10px 0;background:#fafcff}.connection strong,.policy strong{font-size:13px}.connection small,.source,small{font-size:11px;color:#94a3b8;overflow-wrap:anywhere}.policy dl{display:grid;grid-template-columns:68px 1fr;font-size:11px;gap:8px;line-height:1.8}.policy dt{color:#94a3b8}.policy dd{margin:0;color:#64748b}.policy a{font-size:12px;color:#2563eb}.foot{font-size:11px;line-height:1.9;color:#94a3b8;border-top:1px solid #e2e8f0;padding-top:14px}
.canada-shortcuts{padding:14px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;margin-bottom:18px}.canada-shortcuts>strong{font-size:13px;color:#1e40af}.canada-shortcuts>div{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.canada-shortcuts .el-button+.el-button{margin-left:0}.canada-shortcuts>small{display:block;line-height:1.8;color:#64748b}.event-card{padding:16px;background:#fafcff;border:1px solid #e2e8f0;border-left:3px solid #60a5fa;border-radius:7px;margin:12px 0}.event-date{display:flex;align-items:center;justify-content:space-between;color:#2563eb;font-size:12px;margin-bottom:10px}.event-card>strong{font-size:13px;line-height:1.8}.event-card p{font-size:12px;color:#475569;line-height:1.9}.event-card dl{display:grid;grid-template-columns:75px 1fr;gap:9px;font-size:11px;line-height:1.9}.event-card dt{color:#94a3b8}.event-card dd{margin:0;color:#64748b}.event-card a{font-size:12px;color:#2563eb}.canada-events{margin-top:24px;padding-top:4px;border-top:1px solid #e2e8f0}</style>
